from .exceptions import *
from taf.transport.ssh.ssh_keywords import SSHManager as ssh
import re
import logging
import os

logging.basicConfig(format='%(levelname)s::%(message)s')
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


# todo : optimize logging
class CmOperations(object):

    def __init__(self):
        self.export_dir = '/var/opt/oss/global/racops/export/'
        self.import_dir = '/var/opt/oss/global/racops/import/'
        self.alias = 'netact_cm'
        self.connected = False
        self.connection = ssh()

    def connect_to(self, hostname, username, password):
        self._hostname = hostname
        self._username = username
        self._password = password
        self.connection.connect_to(self._hostname, self._username, self._password, alias=self.alias)
        self.connected = True
        logger.info('connection established to {} '.format(self._hostname))
        return self.connected

    def disconnect(self):
        if self.connected:
            try:
                self.connection.disconnect(connection=self.alias)
                logger.debug('disconnected succeffully from {}'.format(self._hostname))
            except Exception as e:
                logger.debug('disconnection failure, raised exception {}'.format(e))
                raise e
            finally:
                self.connected = False

    def contain_error(self, operation_result):
        return re.search(r'Status\sreceived:\sFailed', operation_result)

    def parse_error_details(self, operation_result):
        error_details = re.search(r'Details:\s.*\s', operation_result)
        if error_details:
            return error_details.group()
        return 'No error Details found'

    def parse_statuses(self, operation_result):
        return re.findall(r'Status\sreceived:\s.*\s', operation_result)

    def _run_command(self, command, timeout='5 minutes'):
        try:
            response = self.connection.execute(command=command, timeout=timeout, connection=self.alias)
        except Exception as e:
            logger.debug(' command execution failed due to {}'.format(e))
            raise e
        return response

    def upload(self, bts_dist_name, backup=False):
        # TODO: add timestamp for backup file
        if not isinstance(backup, bool):
            raise ValueError('Backup value should be a bool value : either true or false')
        if backup:
            backup = 'true'
        if not backup:
            backup = 'false'
        bts_id = bts_dist_name.split('-')[-1]
        logging.info('running upload for bts id:{}'.format(bts_id))
        try:
            self._run_command('touch /tmp/empty_file')
            if backup.upper() == 'FALSE':
                logging.info('uploading with no backup')
                response = self._run_command('racclimx.sh -op Upload -DN PLMN-PLMN/' + str(bts_dist_name) + ' -v',
                                             timeout='15 minutes')
                if self.contain_error(response):
                    raise NetactUploadException('Upload Failure, {}'.format(
                        self.parse_error_details(response)
                    ))
            else:
                logging.info('uploading with backup')
                response = self._run_command(
                    'racclimx.sh -op Upload -DN PLMN-PLMN/' + str(bts_dist_name) + ' -takeSranBtsFileBackups true -v',
                    timeout='15 minutes')

            files = self._run_command(
                "find /d/oss/global/var/cmmne3s/work -type f -name 'MRBTS*' -newer /tmp/empty_file")
            if not re.match('MRBTS' + str(bts_id) + '_\d{3,5}_UL.xml.gz', files.strip().split('/')[-1]):
                raise NetactUploadFileNotFound('file not found in netact database')
        except Exception as e:
            raise e
        logging.info('output of upload from NetAct cm: {}'.format(response))
        return response

    def export_plan(self, dist_name, ui_values=True):
        if not isinstance(ui_values, bool):
            raise ValueError('UIValues is a bool value')
        if ui_values:
            ui_values = 'true'
        if not ui_values:
            ui_values = 'false'
        __filename = "Netact{}_exported_file.xml".format(dist_name.split('/')[0])
        __command = "racclimx.sh -op Import_Export -fileFormat RAML2 -importExportOperation actualExport" + \
                    " -DN PLMN-PLMN/{} -fileName {} -UIValues {} " \
                    "-v".format(dist_name, __filename, ui_values.lower())
        __local_dir = '/tmp/NetactCM/'
        try:
            response = self._run_command(__command)
            logger.debug('output of export from netact cm : {}'.format(response))
            if self.contain_error(response):
                raise NetactExportFileException('Export plan Failure, {}'.format(
                    self.parse_error_details(response)
                ))
            if not os.path.isdir(__local_dir):
                os.makedirs(__local_dir)
            self.connection.download_file(self.export_dir + __filename, __local_dir + __filename, self.alias)
            logger.info('file downloaded in {}'.format(self.export_dir + __filename))
            # try :
            #     self._run_command('rm {}'.format(self.export_dir + __filename))
            # except Exception as e :
            #     logger.debug('exception encountered while deleting plan {}'.format(e))
            #     pass
            logger.debug(' file exported and download in {}'.format(__local_dir))
        except Exception as e:
            raise e
        logger.info('file exported to {}'.format(__local_dir))
        return __local_dir + __filename

    def import_plan(self, path_to_file, planname, ui_values=False, objectoperationdefinedinimport=False):

        if not isinstance(ui_values, bool) or not isinstance(objectoperationdefinedinimport, bool):
            raise ValueError('UIValues and obejctoperationdefinedinimport are bool values')
        if ui_values:
            ui_values = 'true'
        if not ui_values:
            ui_values = 'false'
        if objectoperationdefinedinimport:
            objectoperationdefinedinimport = 'true'
        if not objectoperationdefinedinimport:
            objectoperationdefinedinimport = 'false'
        __filename = path_to_file.split('/')[-1]
        __command = "racclimx.sh -op Import_Export -fileFormat RAML2 -importExportOperation planImport " \
                    "-fileName {} -planName {} -UIValues {} " \
                    "-v -useObjectOperationDefinedInImportFile {}".format(__filename, planname, ui_values.lower(),
                                                                          objectoperationdefinedinimport.lower())
        if not os.path.exists(path_to_file):
            raise ValueError("path to file doesn't exists on local machine")
        try:
            self.connection.upload_file(path_to_file, self.import_dir + __filename, self.alias)
            remote_files = self._run_command('ls {}'.format(self.import_dir))
            if __filename not in remote_files:
                raise NetactImportFileNotFOund('file not found in remote files, remote files {}'.format(
                    remote_files))
            response = self._run_command(__command, timeout='15 minutes')
            logger.info('NetAct output from import operation : {}'.format(response))
            if self.contain_error(response):
                raise NetactImportFileException('Import file exception, {}'.format(
                    self.parse_error_details(response)
                ))
        except Exception as e:
            raise e
        return response

    def provision(self, plan_name, provisioning_operation='activate', create_backup=True):

        if not isinstance(create_backup, bool):
            raise ValueError('create_backup should be one of both true or false, value passed should be of type bool')

        if create_backup:
            create_backup = 'true'
        if not create_backup:
            create_backup = 'false'
        __command = "racclimx.sh -op Provision -provisioningOperation {} -createBackupPlan {}  -planName {} -backupPlanName backup_{} -v". \
            format(provisioning_operation, create_backup, plan_name, plan_name)
        if provisioning_operation not in {'activate', 'preactivate'}:
            raise ValueError('provisioning operation need to be one  of : activate , preactivate ')
        logger.info('provisioning plan {} with backup plan name backup_{}'.format(plan_name, plan_name))

        try:
            response = self._run_command(__command)
            logger.debug('NetAct provision output : {}'.format(response))
            if self.contain_error(response):
                logger.debug('plan provision failure')
                logger.debug('statuses received for this operation are : {}'.format(
                    self.parse_statuses(operation_result=response)))
                raise NetactProvisionException('provision plan failure, {}'.format(
                    self.parse_error_details(response)))
        except Exception as e:
            raise NetactProvisionException('provision plan Failure due to {}'.format(e))
        return response

    def validate(self, bts_dist_name, plan_name):
        __command = "racclimx.sh -op Validate -DN PLMN-PLMN/{} -planName {} -sranBtsContentInUse true -v".format(
            bts_dist_name, plan_name)
        logger.debug('validating plan {} with operation scope {} '.format(plan_name, bts_dist_name))
        try:
            response = self._run_command(__command)
            logger.debug('output from plan validation ::  {}'.format(response))
            if self.contain_error(response):
                logger.debug('plan validation error, returned statuses are : {}'.format(self.parse_statuses(
                    operation_result=response
                )))
                raise NetactValidateException('Plan validation Failure, {}'.format(
                    self.parse_error_details(response)))
        except Exception as e:
            raise e
        return response

    def compare_plans(self, plan_name, delat_plan_name):
        __command = "racclimx.sh -op Compare -planName {} -deltaPlanName" \
                    " {} -feedbackLevel objectLevel" \
                    " -v".format(plan_name, delat_plan_name)
        try:
            response = self._run_command(__command)
            logger.debug('output from compare plans :: {}'.format(response))
            if self.contain_error(response):
                logger.debug('compare plans error, operation statuses are:: {}'.format(
                    self.parse_statuses(response)
                ))
                raise NetactOperationException('compare plans failed, {}'.format(self.parse_error_details(
                    response
                )))
        except Exception as e:
            raise e
        return response

    def remove_plan(self, plan_name):
        __command = "racclimx.sh -op planDeletion -planName {} -v".format(plan_name)
        try:
            response = self._run_command(__command)
            logger.debug('remove plan output :: {}'.format(response))
            if self.contain_error(response):
                logger.debug('plan deletion failure, received statuses are :{}'.format(
                    self.parse_statuses(response)
                ))
                raise NetactRemovePLanException('Plan Deletion Failure, {}'.format(
                    self.parse_error_details(response)
                ))
        except Exception as e:
            raise e
        return response

    def activate_plan(self, plan_name):
        __command = "racclimx.sh -op Activate_Pre-Activation -planName {} -sranBtsContentInUse true -v".format(
            plan_name)
        try:
            response = self._run_command(__command)
            logger.debug('output from plan pre activation ::  {}'.format(response))
            if self.contain_error(response):
                logger.debug('plan pre-activation error, returned statuses are : {}'.format(self.parse_statuses(
                    operation_result=response
                )))
                raise NetactPlanPreActivationException('Plan pre-activation Failure, {}'.format(
                    self.parse_error_details(response)))
        except Exception as e:
            raise e
        return response

